(function(root,factory){const api=factory();if(typeof module==='object'&&module.exports)module.exports=api;else root.SourceSizeChoices=api;})(typeof globalThis!=='undefined'?globalThis:this,function(){
function gcd(a,b){while(b){const x=a%b;a=b;b=x;}return a;}
function choices(width,height,video=false){width=Number(width)||1024;height=Number(height)||1024;if(!video){const ratio=width/height,long=Math.max(width,height),minimum=256/Math.min(width/long,height/long);const targets=minimum>768?Array.from({length:5},(_,i)=>Math.round(minimum+(3840-minimum)*i/4)):[768,1280,1920,2560,3840];if(long<=3840&&Math.min(width,height)>=256&&!targets.includes(long)){let i=0,d=Infinity;targets.forEach((v,k)=>{if(k===4)return;const delta=Math.abs(v-long);if(delta<d){d=delta;i=k;}});targets[i]=long;}const result=targets.map(n=>width>=height?Math.round(n)+'x'+Math.round(n/ratio):Math.round(n*ratio)+'x'+Math.round(n));return [...new Set(result)].sort((a,b)=>Number(a.split('x')[0])-Number(b.split('x')[0]));}const g=gcd(width,height);let x=width/g,y=height/g;if(Math.max(x,y)>96){let error=Infinity;for(let h=1;h<=64;h++){const w=Math.max(1,Math.round(width/height*h)),e=Math.abs(w/h-width/height);if(e<error){x=w;y=h;error=e;}}const d=gcd(x,y);x/=d;y/=d;}const maxPixels=video?1327104:1572864;const min=Math.ceil(256/Math.min(x,y)),max=Math.floor(Math.min(1536/Math.max(x,y),Math.sqrt(maxPixels/(x*y))));const candidates=[];for(let n=min;n<=max;n++){let w=x*n,h=y*n;if(video){w=Math.round(w/16)*16;h=Math.round(h/16)*16;}if(w<256||h<256||w>1536||h>1536||w*h>maxPixels)continue;const size=w+'x'+h;if(!candidates.includes(size))candidates.push(size);}if(!candidates.length)return ['512x512'];const result=Array.from({length:Math.min(5,candidates.length)},(_,i)=>candidates[Math.round(i*(candidates.length-1)/Math.max(1,Math.min(5,candidates.length)-1))]);const original=width+'x'+height;if(width>=256&&height>=256&&width<=1536&&height<=1536&&width*height<=maxPixels&&(!video||(width%16===0&&height%16===0))&&!result.includes(original)){let nearest=0,distance=Infinity;result.forEach((s,i)=>{const [w,h]=s.split('x').map(Number),d=Math.abs(Math.log((w*h)/(width*height)));if(d<distance){nearest=i;distance=d;}});result[nearest]=original;}return result.sort((a,b)=>Number(a.split('x')[0])-Number(b.split('x')[0]));}
return {choices};});
